class Node {
public:
    int data;
    Node* left;
    Node* right;
    int height; // Stores the height of the subtree rooted at this node

    Node(int value) {
        data = value;
        left = nullptr;
        right = nullptr;
        height = 1; // New nodes are leaves (height = 1)
    }
};

// Safe helper function to get height of a node (nullptr safe)
int getHeightOfNode(Node* node) {
    if (node == nullptr) return 0;
    return node->height;
}
